using DomainConsole.Shared;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Windows;
namespace DomainConsole;
public sealed partial class RemoteService {
 public static string ReportQueueScript=>DeliveryScripts.Client[..DeliveryScripts.Client.IndexOf("$probe|ConvertTo-Json",StringComparison.Ordinal)]+"\n$probe.Services=(@(Get-Service wuauserv,bits,cryptsvc,UsoSvc -ErrorAction Stop|ForEach-Object {$_.Name+': '+$_.Status}) -join '; ');$probe|ConvertTo-Json -Depth 5 -Compress";
 public async Task<ClientReportProbe> ReadReportQueue(TargetRecord target){using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(45));return JsonSerializer.Deserialize<ClientReportProbe>(await PowerShellBridge.Execute(Invoke(target,ReportQueueScript),timeout.Token),Store.Options)??throw new Exception("Не получены данные очереди.");}
}
public partial class MainWindow {
 readonly Dictionary<string,DateTimeOffset> automaticReportChecks=new(StringComparer.OrdinalIgnoreCase);
 int ReportAgeHours()=>Store.Read("report-age-hours.json",24);
 void SaveReportAge_Click(object sender,RoutedEventArgs e)=>Guard(()=>{if(!int.TryParse(ReportAgeBox.Text,out var hours)||hours<1||hours>720)throw new Exception("Возраст отчёта: 1–720 часов.");Store.Write("report-age-hours.json",hours);Store.Write("automatic-report-recovery-enabled.json",AutomaticReportRepair.IsChecked==true);if(AutomaticReportRepair.IsChecked!=true)CancelUnsentReportRecoveries();Notify("Параметры диагностики и автоматического восстановления отчётности сохранены.");});
 public static string QueueAdvice(ClientReportProbe client,int hours,DateTimeOffset now){if(client.QueueError.Length>0||client.Queues.Count<2)return "Очередь прочитана не полностью. Очистка не рекомендуется без дополнительной диагностики. "+client.QueueError;var old=client.Queues.Any(q=>q.Files>0&&DateTimeOffset.TryParse(q.OldestUtc,out var at)&&now-at>=TimeSpan.FromHours(hours));return old?"Старый отчёт и накопившиеся события: рекомендуется «Восстановить отчётность» после завершения обновлений. Рекомендация применима после завершения текущих операций; автоматическое восстановление зависит от настроек и контрольной проверки.":client.Queues.All(q=>q.Files==0)?"Очередь пуста. Очистка не требуется; предложена расширенная «Диагностика отчёта».":"Есть новые события, но длительное накопление не подтверждено. Не очищайте очередь; проверьте доставку отчёта.";}
 Func<bool> ReportObservationCurrent47(TargetRecord target,WsusReport report){
  var generation=PollingControl43.Token;var server=OverviewServer;var ssl=WsusSsl.IsChecked;
  var serverTarget=ConnectionStore.Capture(new TargetRecord{Host=WsusHost.Text.Trim()});
  return ()=>!closing&&!TransportBudget41.Paused&&!generation.IsCancellationRequested&&CurrentEndpoint(target)&&CurrentEndpoint(serverTarget)&&server==OverviewServer&&ssl==WsusSsl.IsChecked&&reportCache.TryGetValue(target.Host,out var cached)&&ReferenceEquals(cached.Report,report);
 }
 async Task CheckOldReport(ComputerRow row,WsusReport report,Func<TargetRecord,Task<ClientReportProbe>>? probe47=null){var target47=ConnectionStore.Capture(row.Target);var current47=ReportObservationCurrent47(target47,report);if(!current47())return;if(!DateTimeOffset.TryParse(report.LastReportedUtc,out var last)||DateTimeOffset.UtcNow-last>=TimeSpan.FromHours(ReportAgeHours())){if(automaticReportChecks.TryGetValue(row.Host,out var previous)&&DateTimeOffset.UtcNow-previous<TimeSpan.FromMinutes(10))return;automaticReportChecks[row.Host]=DateTimeOffset.UtcNow;string text;try{var client=await (probe47??remote.ReadReportQueue)(target47);if(!current47()){automaticReportChecks.Remove(row.Host);return;}ScheduleReportRecovery(row,report,client);text="## Автоматическая диагностика устаревшего отчёта\nСнимок: "+DateTimeOffset.Now.ToString("dd.MM.yyyy HH:mm:ss")+"\n"+QueueAdvice(client,ReportAgeHours(),DateTimeOffset.UtcNow)+"\n"+string.Join("; ",client.Queues.Select(q=>q.Name+": "+q.Files+" файлов, "+q.Bytes+" байт"))+"\nWUServer: "+client.WUServer+"; WUStatusServer: "+client.WUStatusServer+"; UseWUServer: "+client.UseWUServer+"\nСлужбы: "+client.Services+"\nЭто лёгкая проверка очереди, политик и служб; HTTP отдельно проверяется расширенной диагностикой.";}catch(Exception ex){if(!current47()){automaticReportChecks.Remove(row.Host);return;}text="## Автоматическая диагностика отчётности\nДанные клиента недоступны: "+ex.Message+"\nПричина не установлена; восстановление автоматически не запускается.";}var key=ExecutionRow(row,true).JobId+row.Host;deliveryReports[key]=text;Store.Write("delivery-reports.json",deliveryReports);if(IsCurrent(row))ShowCurrent();}else{var key=ExecutionRow(row,true).JobId+row.Host;if(deliveryReports.TryGetValue(key,out var text)&&text.StartsWith("## Автоматическая")){deliveryReports.Remove(key);Store.Write("delivery-reports.json",deliveryReports);if(IsCurrent(row))ShowCurrent();}}}
}
